using System.ComponentModel;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public class FetchDataTool
{
    [McpServerTool, Description("Fetches data from an external API endpoint and returns the JSON response.")]
    public static async Task<string> FetchData(
        [Description("The API endpoint path to fetch (e.g. /users/1)")] string endpoint,
        IHttpClientFactory httpClientFactory,
        ILogger<FetchDataTool> logger,
        CancellationToken cancellationToken)
    {
        logger.LogInformation("Fetching data from endpoint: {Endpoint}", endpoint);

        using var client = httpClientFactory.CreateClient("ExternalApi");

        try
        {
            var response = await client.GetAsync(endpoint, cancellationToken);
            response.EnsureSuccessStatusCode();

            var content = await response.Content.ReadAsStringAsync(cancellationToken);
            logger.LogInformation("Successfully fetched {Length} characters", content.Length);
            return content;
        }
        catch (HttpRequestException ex)
        {
            logger.LogError(ex, "HTTP request to {Endpoint} failed", endpoint);
            return $"Error: {ex.StatusCode} - {ex.Message}";
        }
    }
}

using System.ComponentModel;
using Microsoft.Extensions.AI;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt to summarize the provided text at a given detail level.")]
    public static IEnumerable<ChatMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Detail level: brief, standard, or detailed")] string detail = "standard")
    {
        var instruction = detail.ToLowerInvariant() switch
